prompt.text:
Repair the complete CommonJS module below and return a corrected complete source file.

Export exactly `{ headersToFields }`.

`headersToFields(headers)` requires an array of strings. Trim each header for its `label`; labels must be non-empty. Produce a key by lowercasing the label, replacing every maximal run of non-ASCII-alphanumeric characters with `_`, and removing leading or trailing underscores. A resulting empty key is malformed. Preserve header order. Repeated normalized keys receive suffixes `_2`, `_3`, and so on. Return fresh `{ key, label }` objects and do not mutate the array. Empty input returns `[]`; malformed input throws `TypeError`.

Known-bad source:

"use strict";

function headersToFields(headers) {
  if (!Array.isArray(headers)) throw new TypeError("headers must be an array");
  const counts = new Map();
  return headers.map((header) => {
    if (typeof header !== "string" || header.trim() === "") {
      throw new TypeError("invalid header");
    }
    const label = header.trim();
    const base = label.toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "");
    if (base === "") throw new TypeError("header has no key characters");
    const count = counts.get(base) || 0;
    counts.set(base, count + 1);
    return { key: count === 0 ? base : base + "_" + count, label };
  });
}

module.exports = { headersToFields };

