"use strict";

const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api), ["headersToFields"]);
const { headersToFields } = api;

const headers = [" First Name ", "FIRST--NAME", "Age (Years)", "postal.code", "Café", "x", "x", "x"];
const snapshot = headers.slice();
const fields = headersToFields(headers);
assert.deepStrictEqual(fields, [
  { key: "first_name", label: "First Name" },
  { key: "first_name_2", label: "FIRST--NAME" },
  { key: "age_years", label: "Age (Years)" },
  { key: "postal_code", label: "postal.code" },
  { key: "caf", label: "Café" },
  { key: "x", label: "x" },
  { key: "x_2", label: "x" },
  { key: "x_3", label: "x" }
]);
assert.deepStrictEqual(headers, snapshot);
assert.notStrictEqual(fields[0], fields[1]);
fields[0].label = "changed";
assert.strictEqual(headers[0], " First Name ");
assert.deepStrictEqual(headersToFields([]), []);
assert.deepStrictEqual(headersToFields(["__A___B__"]), [{ key: "a_b", label: "__A___B__" }]);

for (const invalid of [null, {}, "header", [1], [""], ["   "], ["---"], ["é"], ["ok", null]]) {
  assert.throws(() => headersToFields(invalid), TypeError);
}

